use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub struct TrainingSample { pub outcome: f64, pub features: Vec<f64> }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModelError { EmptyName, EmptyTraining, MissingModel, InvalidNumber, EmptyFeatures, DimensionMismatch }

#[derive(Debug, Clone, Default)]
pub struct SampleStore { models: HashMap<String, Vec<TrainingSample>> }

impl SampleStore {
    pub fn new() -> Self { Self::default() }

    pub fn train(&mut self, name: &str, updates: &[TrainingSample]) -> Result<(), ModelError> {
        if name.is_empty() { return Err(ModelError::EmptyName); }
        if updates.is_empty() { return Err(ModelError::EmptyTraining); }
        let existing_dimension = self.models.get(name).and_then(|v| v.first()).map(|s| s.features.len());
        let dimension = existing_dimension.unwrap_or(updates[0].features.len());
        for sample in updates {
            if !sample.outcome.is_finite() || sample.features.iter().any(|v| !v.is_finite()) {
                return Err(ModelError::InvalidNumber);
            }
            if sample.features.is_empty() { return Err(ModelError::EmptyFeatures); }
            if sample.features.len() != dimension { return Err(ModelError::DimensionMismatch); }
        }
        self.models.entry(name.to_owned()).or_default().extend_from_slice(updates);
        Ok(())
    }

    pub fn predict(&self, name: &str, queries: &[Vec<f64>]) -> Result<Vec<f64>, ModelError> {
        if name.is_empty() { return Err(ModelError::EmptyName); }
        let samples = self.models.get(name).ok_or(ModelError::MissingModel)?;
        let dimension = samples[0].features.len();
        let mut output = Vec::with_capacity(queries.len());
        for query in queries {
            if query.iter().any(|v| !v.is_finite()) { return Err(ModelError::InvalidNumber); }
            if query.is_empty() { return Err(ModelError::EmptyFeatures); }
            if query.len() != dimension { return Err(ModelError::DimensionMismatch); }
            let mut best = None;
            for sample in samples {
                let distance = sample.features.iter().zip(query).map(|(a, b)| (a - b) * (a - b)).sum::<f64>();
                if best.map_or(true, |(old, _)| distance <= old) {
                    best = Some((distance, sample.outcome));
                }
            }
            output.push(best.unwrap().1);
        }
        Ok(output)
    }
}
