#[path = "solution.rs"]
mod solution;

use solution::*;

fn sample(outcome: f64, features: &[f64]) -> TrainingSample {
    TrainingSample { outcome, features: features.to_vec() }
}

#[test]
fn trains_and_predicts_nearest_samples() {
    let mut store = SampleStore::new();
    store.train("model", &[sample(10.0, &[0.0, 0.0]), sample(20.0, &[4.0, 0.0])]).unwrap();
    assert_eq!(store.predict("model", &[vec![0.5, 0.0], vec![3.5, 0.0]]), Ok(vec![10.0, 20.0]));
}

#[test]
fn equal_distance_ties_choose_earliest_insertion() {
    let mut store = SampleStore::new();
    store.train("m", &[sample(1.0, &[0.0]), sample(2.0, &[2.0])]).unwrap();
    assert_eq!(store.predict("m", &[vec![1.0]]), Ok(vec![1.0]));

    store.train("m", &[sample(3.0, &[1.0])]).unwrap();
    assert_eq!(store.predict("m", &[vec![1.0]]), Ok(vec![3.0]));
}

#[test]
fn training_validation_and_dimensions_are_enforced() {
    let mut store = SampleStore::new();
    assert_eq!(store.train("", &[sample(1.0, &[1.0])]), Err(ModelError::EmptyName));
    assert_eq!(store.train("m", &[]), Err(ModelError::EmptyTraining));
    assert_eq!(store.train("m", &[sample(1.0, &[])]), Err(ModelError::EmptyFeatures));
    assert_eq!(store.train("m", &[sample(f64::NAN, &[1.0])]), Err(ModelError::InvalidNumber));
    assert_eq!(store.train("m", &[sample(1.0, &[f64::INFINITY])]), Err(ModelError::InvalidNumber));

    store.train("m", &[sample(1.0, &[0.0, 0.0])]).unwrap();
    assert_eq!(store.train("m", &[sample(2.0, &[1.0])]), Err(ModelError::DimensionMismatch));
}

#[test]
fn failed_training_is_atomic_for_existing_and_new_models() {
    let mut store = SampleStore::new();
    store.train("existing", &[sample(1.0, &[0.0])]).unwrap();
    let updates = [sample(2.0, &[10.0]), sample(3.0, &[1.0, 2.0])];
    assert_eq!(store.train("existing", &updates), Err(ModelError::DimensionMismatch));
    assert_eq!(store.predict("existing", &[vec![10.0]]), Ok(vec![1.0]));

    assert_eq!(store.train("new", &updates), Err(ModelError::DimensionMismatch));
    assert_eq!(store.predict("new", &[]), Err(ModelError::MissingModel));
}

#[test]
fn prediction_validation_and_empty_queries_work() {
    let mut store = SampleStore::new();
    store.train("m", &[sample(4.0, &[1.0, 2.0])]).unwrap();
    assert_eq!(store.predict("m", &[]), Ok(vec![]));
    assert_eq!(store.predict("", &[]), Err(ModelError::EmptyName));
    assert_eq!(store.predict("missing", &[]), Err(ModelError::MissingModel));
    assert_eq!(store.predict("m", &[vec![]]), Err(ModelError::EmptyFeatures));
    assert_eq!(store.predict("m", &[vec![1.0]]), Err(ModelError::DimensionMismatch));
    assert_eq!(store.predict("m", &[vec![1.0, f64::NAN]]), Err(ModelError::InvalidNumber));
}

#[test]
fn prediction_does_not_mutate_queries_or_store() {
    let mut store = SampleStore::new();
    store.train("m", &[sample(7.0, &[1.0])]).unwrap();
    let queries = vec![vec![1.0], vec![2.0]];
    let before = queries.clone();
    assert_eq!(store.predict("m", &queries), Ok(vec![7.0, 7.0]));
    assert_eq!(queries, before);
    assert_eq!(store.predict("m", &queries), Ok(vec![7.0, 7.0]));
}

